/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { readMinor } from './work/lib/money.mjs';

const readJson = (path) => JSON.parse(readFileSync(path, 'utf8'));
const settlement = readJson('settlement.json');
assert.deepEqual(settlement.map(({ id }) => id), readJson('work/rows.json').map(({ id }) => id));
assert.deepEqual(settlement.map(({ net }) => net), [
  { unit: 'EUR-cent', value: '153' },
  { unit: 'EUR-cent', value: '-30' },
]);
for (const { net, fee } of settlement) {
  assert.equal(readMinor(net.value).toString(), net.value);
  assert.deepEqual(Object.keys(fee), ['status', 'authority', 'requiredDecision']);
  assert.equal(fee.status, 'blocked');
  assert.equal(fee.authority, 'R-35');
  assert.match(fee.requiredDecision, /Марине.*числитель и знаменатель.*правило округления.*отдела B/);
}
console.log('Verified both rows, net DTO round trips, and blocked fee decisions.');
NODE"

